INSERT INTO  /* com.seinfo.protoA.util.token.TokenMapper.insertTokenBanned */
	zzz_token_denied
(
 	 token_usr_id
   , token_key
   , token_denied_desc
   , reg_dt
) VALUES (
	 #{userUid}
	,#{tokenKey}
	,#{tokenDeniedDesc}
	,now()
)

INSERT INTO  /* com.seinfo.protoA.util.token.TokenMapper.insertTokenAccess */
	zzz_token_access
(
	token_user_id
  , token_key
  , user_ip_address
  , user_agent
  , reg_dt
) VALUES (
	#{userUid}
	,#{tokenKey}
	,#{userIpAddress}
	,#{userAgent}
	,now()
)
